// =========================================================================
// MONTREAL TÊNIS CLUBE — AUDITORIA DIÁRIA DE CHECKLISTS E ROTINAS (4 CHECKPOINTS)
// =========================================================================

// 1. CONFIGURAÇÃO DE DESTINATÁRIOS
// Deixe 'true' para testar primeiro no seu número pessoal (ID 1511)
// Mude para 'false' para enviar aos 2 números oficiais da diretoria/gestão (IDs 125 e 4)
const MODO_TESTE = true;

const DESTINATARIOS_TESTE = [
  { contact_id: 1511, nome_dest: 'Vinicius (Teste)' }
];

const DESTINATARIOS_PRODUCAO = [
  { contact_id: 125, nome_dest: 'Montreal (+55 41 93618-3407)' },
  { contact_id: 4, nome_dest: 'Gestão (+55 41 8809-7503)' }
];

const DESTINATARIOS = MODO_TESTE ? DESTINATARIOS_TESTE : DESTINATARIOS_PRODUCAO;

// 2. MATRIZ OFICIAL DAS 22 TAREFAS (Planilha Excel Montreal)
const TODAS_AS_TAREFAS = [
  // --- TURNO DA MANHÃ ---
  { id: 'm_1', time: '07:00', minutes: 7 * 60 + 0, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Conferir no sistema quais quadras serão utilizadas e acender as luzes' },
  { id: 'm_2', time: '07:20', minutes: 7 * 60 + 20, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Coletar o lixo do estacionamento e colocar para fora' },
  { id: 'm_3', time: '07:30', minutes: 7 * 60 + 30, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Conferir os banheiros e repor papel-toalha e papel higiênico' },
  { id: 'm_4', time: '07:40', minutes: 7 * 60 + 40, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Passar pano seco na mesa da recepção e nas mesas das quadras' },
  { id: 'm_5', time: '07:50', minutes: 7 * 60 + 50, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Conferir mensagens pendentes e dar sequência às matrículas dos alunos' },
  { id: 'm_6', time: '09:00', minutes: 9 * 60 + 0, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Conferir com os professores a necessidade de iluminação conforme for clareando' },
  { id: 'm_7', time: '09:20', minutes: 9 * 60 + 20, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Passar vassoura na escada, corredor e área de convivência' },
  { id: 'm_8', time: '11:00', minutes: 11 * 60 + 0, colab: 'Cynthia', shift: 'Manhã', days: 'seg_qua_sex', desc: 'Passar pano úmido na área de convivência e nos banheiros' },
  { id: 'm_9', time: '13:00', minutes: 13 * 60 + 0, colab: 'Cynthia', shift: 'Manhã', days: 'all', desc: 'Conferir se todas as quadras estão feitas e prontas para uso' },

  // --- TURNO DA TARDE ---
  { id: 't_1', time: '15:00', minutes: 15 * 60 + 0, colab: 'Lucas', shift: 'Tarde', days: 'all', desc: 'Conferir mensagens e dar sequência às pendências' },
  { id: 't_2', time: '15:40', minutes: 15 * 60 + 40, colab: 'Lucas', shift: 'Tarde', days: 'all', desc: 'Passar vassoura na área de convivência e banheiros' },
  { id: 't_3', time: '17:00', minutes: 17 * 60 + 0, colab: 'Alex', shift: 'Tarde', days: 'all', desc: 'Conferir e repor os papéis dos banheiros' },
  { id: 't_4', time: '17:30', minutes: 17 * 60 + 30, colab: 'Alex', shift: 'Tarde', days: 'all', desc: 'Circular pelo clube e conferir se está tudo em ordem' },
  { id: 't_5', time: '17:30', minutes: 17 * 60 + 30, colab: 'Alex', shift: 'Tarde', days: 'all', desc: 'Conferir se a agenda está de acordo com as quadras utilizadas' },
  { id: 't_6', time: '18:20', minutes: 18 * 60 + 20, colab: 'Lucas e Alex', shift: 'Tarde', days: 'ter_qui', desc: 'Varrer corredor e escada' },

  // --- TURNO DA NOITE ---
  { id: 'n_1', time: '19:00', minutes: 19 * 60 + 0, colab: 'Alex', shift: 'Noite', days: 'all', desc: 'Conferir se a agenda está de acordo com as quadras utilizadas' },
  { id: 'n_2', time: '20:00', minutes: 20 * 60 + 0, colab: 'Lucas e Alex', shift: 'Noite', days: 'all', desc: 'Deixar o balcão organizado' },
  { id: 'n_3', time: '21:30', minutes: 21 * 60 + 30, colab: 'Lucas', shift: 'Noite', days: 'all', desc: 'Varrer toda a área de convivência' },
  { id: 'n_4', time: '21:30', minutes: 21 * 60 + 30, colab: 'Alex', shift: 'Noite', days: 'all', desc: 'Retirar todo o lixo e colocar no estacionamento para coleta' },
  { id: 'n_5', time: '22:00', minutes: 22 * 60 + 0, colab: 'Lucas e Alex', shift: 'Noite', days: 'all', desc: 'Preparar as quadras: molhar e deixar em condições de uso' },
  { id: 'n_6', time: '22:30', minutes: 22 * 60 + 30, colab: 'Lucas e Alex', shift: 'Noite', days: 'all', desc: 'Conferir se o botão da bomba de água está desligado' },
  { id: 'n_7', time: '23:00', minutes: 23 * 60 + 0, colab: 'Lucas e Alex', shift: 'Noite', days: 'all', desc: 'Conferir se as portas de baixo estão trancadas' }
];

// 3. IDENTIFICAÇÃO DO MOMENTO ATUAL (Horário de Brasília)
const spNow = new Date();
const diaSemana = spNow.getDay(); // 0=Dom, 1=Seg, 2=Ter, 3=Qua, 4=Qui, 5=Sex, 6=Sáb
const horaStr = spNow.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
const dataStr = spNow.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit' });

// Obter horas e minutos em São Paulo para comparação
const horaSP = parseInt(spNow.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false }), 10);
const minSP = parseInt(spNow.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', minute: '2-digit' }), 10);
const minutosAgora = horaSP * 60 + minSP;

// Mapeamento dos 4 Checkpoints Oficiais
let checkpointNome = '';
let limiteMinutos = minutosAgora;

if (minutosAgora >= (11 * 60 + 30) && minutosAgora <= (13 * 60 + 30)) {
  checkpointNome = 'Conferência das 12:00 (Fim da Manhã)';
  limiteMinutos = 12 * 60; // Tarefas da manhã até 12:00
} else if (minutosAgora > (13 * 60 + 30) && minutosAgora <= (16 * 60 + 30)) {
  checkpointNome = 'Conferência das 15:45 (Meio da Tarde)';
  limiteMinutos = 15 * 60 + 45;
} else if (minutosAgora > (16 * 60 + 30) && minutosAgora <= (19 * 60 + 30)) {
  checkpointNome = 'Conferência das 18:25 (Fim da Tarde)';
  limiteMinutos = 18 * 60 + 25;
} else if (minutosAgora > (19 * 60 + 30) && minutosAgora <= (23 * 60 + 59)) {
  checkpointNome = 'Conferência das 22:50 (Fechamento Noite)';
  limiteMinutos = 22 * 60 + 50;
} else {
  checkpointNome = `Conferência Manual (${horaStr})`;
  limiteMinutos = minutosAgora;
}

// 4. LEITURA DAS TAREFAS CONCLUÍDAS DO SUPABASE
const allInputs = $input.all();
const completedRows = [];
for (const item of allInputs) {
  const j = item.json;
  if (Array.isArray(j)) {
    completedRows.push(...j);
  } else if (j && j.task_id) {
    completedRows.push(j);
  } else if (j && j.data && Array.isArray(j.data)) {
    completedRows.push(...j.data);
  }
}
const concluidasSet = new Set(completedRows.map(r => r.task_id).filter(Boolean));

// 5. FILTRAGEM DE TAREFAS QUE DEVERIAM TER SIDO CONCLUÍDAS HOJE
const tarefasEsperadas = TODAS_AS_TAREFAS.filter(t => {
  // 5.1 Deve estar dentro do horário limite do checkpoint
  if (t.minutes > limiteMinutos) return false;

  // 5.2 Validação de Dias Específicos:
  if (t.days === 'seg_qua_sex') {
    // Seg (1), Qua (3), Sex (5)
    if (diaSemana !== 1 && diaSemana !== 3 && diaSemana !== 5) return false;
  }
  if (t.days === 'ter_qui') {
    // Ter (2), Qui (4)
    if (diaSemana !== 2 && diaSemana !== 4) return false;
  }

  return true;
});

// 6. IDENTIFICAÇÃO DAS PENDÊNCIAS
const tarefasPendentes = tarefasEsperadas.filter(t => !concluidasSet.has(t.id));

// Se não houver pendências, não envia alerta de cobrança
if (tarefasPendentes.length === 0) {
  return [{
    json: {
      tem_pendencias: false,
      checkpoint: checkpointNome,
      total_esperadas: tarefasEsperadas.length,
      total_concluidas: concluidasSet.size,
      mensagem: `Parabéns! Todas as ${tarefasEsperadas.length} tarefas esperadas até às ${horaStr} foram concluídas.`,
      contact_id: null
    }
  }];
}

// 7. MONTAGEM DA MENSAGEM NO PADRÃO MONTREAL
let msg = `🚨 *MONTREAL | Auditoria de Rotinas & Checklist Diário*\n`;
msg += `⏰ *${checkpointNome}*\n`;
msg += `📅 *${dataStr.charAt(0).toUpperCase() + dataStr.slice(1)}*\n\n`;
msg += `Identificamos *${tarefasPendentes.length} tarefa(s) pendente(s)* que deveriam ter sido realizadas e registradas no sistema até este horário:\n`;

tarefasPendentes.forEach((t, i) => {
  const tagDia = t.days === 'seg_qua_sex' ? ' _(Seg/Qua/Sex)_' : (t.days === 'ter_qui' ? ' _(Ter/Qui)_' : '');
  msg += `\n${i + 1}️⃣ ⏰ *${t.time}* | 👤 *${t.colab}*${tagDia}\n`;
  msg += `📌 *${t.desc}*\n`;
});

msg += `\n⚠️ *Ação necessária:* Por favor, realizem as rotinas pendentes e marquem a conclusão no portal interno:\n`;
msg += `🔗 *https://portal.montrealtenis.com.br/#limpeza*`;

return DESTINATARIOS.map(dest => ({
  json: {
    tem_pendencias: true,
    contact_id: dest.contact_id,
    nome_dest: dest.nome_dest,
    checkpoint: checkpointNome,
    total_pendentes: tarefasPendentes.length,
    total_esperadas: tarefasEsperadas.length,
    mensagem: msg
  }
}));
